<script setup lang="ts">import {computed} from 'vue';import {useRoute} from 'vue-router';import {loans,money} from '../data/demo';import PageNav from '../components/PageNav.vue';const loan=computed(()=>loans.find(b=>b.id===Number(useRoute().params.id))||loans[0])</script>
<template><main class="page detail-page"><PageNav title="借款详情" right="合同"/><section class="detail-hero"><van-tag :type="loan.status==='已结清'?'success':'primary'" round>{{loan.status}}</van-tag><p>借款金额</p><strong>{{money(loan.amount)}}</strong><span>订单编号 {{loan.id}}</span></section><van-cell-group inset><van-cell title="借款期限" :value="`${loan.term} 期`"/><van-cell title="年化利率" :value="`${loan.annualRate}%`"/><van-cell title="借款用途" :value="loan.purpose"/><van-cell title="收款账户" :value="loan.bank"/></van-cell-group><section class="section-block"><h2>还款进度</h2><van-progress :percentage="Math.round(loan.repaid/loan.term*100)" stroke-width="8" color="#14b8a6"/><div class="progress-caption"><span>已还 {{loan.repaid}} 期</span><span>共 {{loan.term}} 期</span></div></section><section v-if="loan.status!=='已结清'" class="section-block installment"><span>下期应还</span><strong>{{money(loan.nextAmount)}}</strong><p>{{loan.nextDate}} 自动提醒</p></section><van-button v-if="loan.status!=='已结清'" class="fixed-cta" type="primary" round block :to="`/repay/${loan.id}`">立即还款</van-button></main></template>
